INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `BroadcastTextID0`, `lang0`, `Probability0`, `em0_0`, `em0_1`, `em0_2`, `em0_3`, `em0_4`, `em0_5`)
VALUES
(25013, 'Greetings, $c. Did you know that Runemasters engrave runes onto their skin, just like a tattoo to better harness their power?$B$BLet''s see if you have any room left on your skin for some..', 'Greetings, $c. Did you know that Runemasters engrave runes onto their skin, just like a tattoo to better harness their power?$B$BLet''s see if you have any room left on your skin for some..', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(32035, 'The element''s guide me, and I can teach them to guide you too.', 'The element''s guide me, and I can teach them to guide you too.', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(35317, 'Do not try to tell me how to practice Venomancy, $n.$B$BI was there when the poisonous words were written.$B$BI am the teacher. Now learn.', 'Do not try to tell me how to practice Venomancy, $n.$B$BI was there when the poisonous words were written.$B$BI am the teacher. Now learn.', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(75022, 'Life and death are but tools in the hands of a skilled Bloodmage. Let me show you their secrets.', 'Life and death are but tools in the hands of a skilled Bloodmage. Let me show you their secrets.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(75041, 'Fel magic burns within you, Felsworn. Let me teach you to channel that corrupt power.', 'Fel magic burns within you, Felsworn. Let me teach you to channel that corrupt power.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(75050, 'A true Guardian stands between the innocent and those who would harm them. You have this calling.', 'A true Guardian stands between the innocent and those who would harm them. You have this calling.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(75063, 'Darkness and steel combined - this is the Knight of Xoroth''s way. You understand.', 'Darkness and steel combined - this is the Knight of Xoroth''s way. You understand.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(75432, 'Greetings, young mortal. Let me teach you how to control the sands of time.', 'Greetings, young mortal. Let me teach you how to control the sands of time.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(75441, 'Get ova here, ''mon. Let me teach ya how to hex ya foes.', 'Get ova here, ''mon. Let me teach ya how to hex ya foes.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(102056, 'The wind doesn''t carry your scent as it does a Ranger''s, $C. Seek your training elsewhere.', 'The wind doesn''t carry your scent as it does a Ranger''s, $C. Seek your training elsewhere.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(102292, 'The dark magicks require a Witch Hunter''s expertise, $C. I cannot train you in these arts.', 'The dark magicks require a Witch Hunter''s expertise, $C. I cannot train you in these arts.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(102296, 'The storms speak only to Stormbringers, $C. Your spirit lacks the tempest needed for such power.', 'The storms speak only to Stormbringers, $C. Your spirit lacks the tempest needed for such power.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(102542, 'The Light shines differently for each soul, $C, but it does not call you to be a Templar.', 'The Light shines differently for each soul, $C, but it does not call you to be a Templar.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(125013, 'There''s no room on your skin for runic tattoos, $C, because you lack the Runemaster''s spirit to hold them.', 'There''s no room on your skin for runic tattoos, $C, because you lack the Runemaster''s spirit to hold them.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(125018, 'My gears don''t turn for just anyone, $C. Tinker training requires a mechanical mind you clearly lack.', 'My gears don''t turn for just anyone, $C. Tinker training requires a mechanical mind you clearly lack.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(125024, 'Hey! Here''s a challenge - try learning fire magic without being a Pyromancer, $C. Spoiler: you can''t!', 'Hey! Here''s a challenge - try learning fire magic without being a Pyromancer, $C. Spoiler: you can''t!', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(132019, 'The dark arts of Xoroth are not for the weak-willed, $C. Only true Knights of Xoroth can master what I teach without losing their souls.', 'The dark arts of Xoroth are not for the weak-willed, $C. Only true Knights of Xoroth can master what I teach without losing their souls.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(132029, 'The shade knows its own kind, $C. I sense no Reaper''s darkness within your soul.', 'The shade knows its own kind, $C. I sense no Reaper''s darkness within your soul.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(132035, 'The elements guide only true Primalists, $C. They do not hear your call.', 'The elements guide only true Primalists, $C. They do not hear your call.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(132044, 'The whispers do not call to you, $C. Only those chosen as Cultists may hear the dark truths I possess.', 'The whispers do not call to you, $C. Only those chosen as Cultists may hear the dark truths I possess.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(135317, 'I was there when the poisonous words were written, $C, and none of them were written for non-Venomancers like you.', 'I was there when the poisonous words were written, $C, and none of them were written for non-Venomancers like you.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(139218, 'Your blood sings the wrong song, $C. I only teach fellow Bloodmages the secrets of sanguine power.', 'Your blood sings the wrong song, $C. I only teach fellow Bloodmages the secrets of sanguine power.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(175050, 'The Guardian''s burden requires selfless devotion, $C. You are too focused on yourself.', 'The Guardian''s burden requires selfless devotion, $C. You are too focused on yourself.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(175432, 'Time itself rejects your presence, young $C. I can only guide those chosen to walk the path of the Chronomancer.', 'Time itself rejects your presence, young $C. I can only guide those chosen to walk the path of the Chronomancer.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(175441, 'De witch doctor''s path is not for de spiritually blind, $C. Seek other callings.', 'De witch doctor''s path is not for de spiritually blind, $C. Seek other callings.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(254046, 'The Light has favored you, Templar. I can teach you how to best wield that favor, if you''d let me.', 'The Light has favored you, Templar. I can teach you how to best wield that favor, if you''d let me.', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(254068, 'Another Necromancer? What a pleasant surprise!$B$BThe necromantic are hardly well-received by the masses. Ah, but I''m sure you understand that perfectly by now already.$B$BI imagine you''re here to learn, so let''s not waste time on pleasantries, shall we?', 'Another Necromancer? What a pleasant surprise!$B$BThe necromantic are hardly well-received by the masses. Ah, but I''m sure you understand that perfectly by now already.$B$BI imagine you''re here to learn, so let''s not waste time on pleasantries, shall we?', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(287575, 'The path of the Barbarian is not for the weak-willed, $C. Seek your destiny elsewhere.', 'The path of the Barbarian is not for the weak-willed, $C. Seek your destiny elsewhere.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(305859, 'The stars do not sing for you, $C. Only Starcallers can hear their celestial wisdom.', 'The stars do not sing for you, $C. Only Starcallers can hear their celestial wisdom.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(354109, 'You aren''t a Necromancer, and you would never understand the power of bone unless I freed them from your worthless flesh.', 'You aren''t a Necromancer, and you would never understand the power of bone unless I freed them from your worthless flesh.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(387564, 'The Sun does not call to you, $C. These sacred teachings of solar power are reserved for true Sun Clerics.', 'The Sun does not call to you, $C. These sacred teachings of solar power are reserved for true Sun Clerics.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(930012, 'Rage is a weapon like any other, Barbarian. Let me teach you to wield it.', 'Rage is a weapon like any other, Barbarian. Let me teach you to wield it.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(930015, 'Hexes, curses and the wretches who cast them - a Witch Hunter answers them all. Let me sharpen your craft.', 'Hexes, curses and the wretches who cast them - a Witch Hunter answers them all. Let me sharpen your craft.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(930016, 'The storm answers those bold enough to call it, Stormbringer. Let me teach you to command the thunder.', 'The storm answers those bold enough to call it, Stormbringer. Let me teach you to command the thunder.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(930021, 'The wilds reward a patient eye and a steady aim, Ranger. Let me teach you what the hunt has taught me.', 'The wilds reward a patient eye and a steady aim, Ranger. Let me teach you what the hunt has taught me.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(930024, 'The flames dance for you, Pyromancer. Let me teach you to make them roar.', 'The flames dance for you, Pyromancer. Let me teach you to make them roar.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(930025, 'The whispers have chosen you, Cultist. Let me teach you to listen - and to answer.', 'The whispers have chosen you, Cultist. Let me teach you to listen - and to answer.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(930026, 'The stars have marked your path, Starcaller. Let me teach you to call down their light.', 'The stars have marked your path, Starcaller. Let me teach you to call down their light.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(930027, 'The Sun''s warmth flows through you, Sun Cleric. Let me teach you to share its radiance.', 'The Sun''s warmth flows through you, Sun Cleric. Let me teach you to share its radiance.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(930028, 'Gears, gadgets and a healthy dose of explosives - that''s the Tinker''s way. Let me show you a few tricks.', 'Gears, gadgets and a healthy dose of explosives - that''s the Tinker''s way. Let me show you a few tricks.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(930030, 'Every soul meets its ending, Reaper. Let me teach you to be the one who brings it.', 'Every soul meets its ending, Reaper. Let me teach you to be the one who brings it.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(930114, 'The fel does not burn within you, $C. Only the Felsworn can bear what I teach.', 'The fel does not burn within you, $C. Only the Felsworn can bear what I teach.', 0, 0, 1, 0, 0, 0, 0, 0, 0);
